     */
    function validateInputProof(
        bytes32 handle,
        address owner,
        bytes calldata proof,
        TEEType teeType
    ) external;

    /**
     * Validates the decryption proof issued by the gateway for a given handle.
     * The proof must be signed by the configured gateway.
